<template><AppFrame><section class="page-heading mb-6"><div><p class="eyebrow">PERSONAL</p><h1 class="text-h4 font-weight-bold">Técnicos</h1></div><v-btn color="primary" prepend-icon="mdi-account-plus" @click="dialog=true">Nuevo técnico</v-btn></section><v-card class="panel" elevation="0" rounded="xl"><v-data-table :headers="headers" :items="items"><template #item.activo="{item}"><v-chip :color="item.activo?'success':'grey'" size="small">{{item.activo?'Activo':'Inactivo'}}</v-chip></template></v-data-table></v-card><v-dialog v-model="dialog" max-width="560"><v-card title="Nuevo técnico"><v-card-text><v-text-field v-model="form.numero_empleado" label="Número de empleado"/><v-text-field v-model="form.nombre" label="Nombre"/><v-text-field v-model="form.area" label="Área"/></v-card-text><v-card-actions><v-spacer/><v-btn @click="dialog=false">Cancelar</v-btn><v-btn color="primary" @click="save">Guardar</v-btn></v-card-actions></v-card></v-dialog></AppFrame></template><script setup lang="ts">import{onMounted,reactive,ref}from'vue';import AppFrame from '@/components/AppFrame.vue';import api from '@/services/api';const items=ref<any[]>([]),dialog=ref(false),form=reactive({numero_empleado:'',nombre:'',area:''});const headers=[{title:'Número',key:'numero_empleado'},{title:'Nombre',key:'nombre'},{title:'Área',key:'area'},{title:'Estado',key:'activo'}];async function load(){items.value=(await api.get('/admin/tecnicos')).data}async function save(){await api.post('/admin/tecnicos',form);dialog.value=false;Object.assign(form,{numero_empleado:'',nombre:'',area:''});load()}onMounted(load)</script><style scoped>.page-heading{display:flex;justify-content:space-between;align-items:center}.eyebrow{color:#1976d2;font-weight:700;letter-spacing:.14em}.panel{border:1px solid #e5e7eb}</style>
